from pathlib import Path
import re,json,subprocess,hashlib,unicodedata,datetime,collections
ROOT=Path.cwd();BASELINE='227f62ed57dedc46b6c1d3bef2ed67b4e3612d3b';CONFIG='_quarto-html.yml'
def gittext(p):return subprocess.check_output(['git','show',BASELINE+':'+p],text=True)
def configured(s):return re.findall(r'^\s*-\s+(?:part:\s+)?([^\s]+\.qmd)\s*$',s,re.M)
paths=configured(Path(CONFIG).read_text());oldpaths=configured(gittext(CONFIG));assert len(paths)==len(set(paths))==61
old={p:gittext(p) for p in oldpaths};current={p:Path(p).read_text() for p in paths}
refpat=re.compile(r'^::: \{\.reference\}[^\S\n]*\n(.*?)\n:::[^\S\n]*$',re.M|re.S)
def refs(s):return [(re.sub(r'\s+',' ',m.group(1)).strip(),s[:m.start()].count('\n')+1) for m in refpat.finditer(s)]
def normalize(s):
 s=re.sub(r'\s+',' ',s).strip().rstrip('.').casefold().replace('’',"'").replace('“','"').replace('”','"').replace('–','-').replace('—','-')
 s=re.sub(r'[*_`]','',s);s=re.sub(r'\s*([,;:()])\s*',r'\1',s)
 return s
def textkey(s):return ''.join(c for c in unicodedata.normalize('NFKD',s.casefold()) if not unicodedata.combining(c))
def bibliography_sort_key(s):
 plain=re.sub(r'[*_`]','',s)
 m=re.search(r'\((\d{4}[a-z]?(?:,[^)]*)?|n\.d\.)\)',plain)
 compact=lambda x:re.sub(r'[^a-z0-9]','',textkey(x))
 if not m:return (((compact(plain),''),),(-1,''),'')
 author=plain[:m.start()]
 # Independently recognize surname/initial groups with a regex, rather than
 # importing the production comma-field sorting helper.
 people=re.findall(r'(?:^|,\s*)(?:&\s*)?([^,]+),\s*((?:[A-ZÀ-ÖØ-Þ]\.[ \-]*)+)',author)
 author_keys=tuple((compact(surname),compact(initials)) for surname,initials in people)
 if not author_keys:author_keys=((compact(author),''),)
 date=m.group(1);year_match=re.match(r'(\d{4})([a-z]?)',date)
 year=(int(year_match.group(1)),year_match.group(2)) if year_match else (-1,'')
 title=plain[m.end():].strip('. ');title=re.sub(r'^(?:a|an|the)\s+','',title,flags=re.I)
 return author_keys,year,compact(title)
def workkey(s):
 # A DOI-enriched citation and its old version must still represent the same work.
 s=re.sub(r'\[([^]]+)\]\([^)]*\)',r'\1',s)
 s=re.sub(r'https?://\S+','',s)
 s=re.sub(r'[*_`]','',s)
 m=re.search(r'\((\d{4}[a-z]?(?:,[^)]*)?|n\.d\.)\)',s)
 if not m:return 'fallback:'+normalize(s)
 author=s[:m.start()];year=m.group(1).split(',')[0]
 rest=s[m.end():].lstrip('. ')
 title=re.split(r'\.\s+',rest,maxsplit=1)[0]
 compact=lambda x:re.sub(r'[^a-z0-9]','',textkey(x))
 return compact(author)+'|'+compact(year)+'|'+compact(title)
def groups(d,key):
 out={}
 for p,s in d.items():
  for entry,line in refs(s):out.setdefault(key(entry),[]).append({'file':p,'line':line,'reference':entry})
 return out
oldentries=groups(old,normalize);newentries=groups(current,normalize);oldworks=groups(old,workkey);newworks=groups(current,workkey)
reference_lists=[];unsorted=[]
for p,s in current.items():
 r=refs(s)
 if not(p.startswith('chapters/') or p.startswith('appendices/') or p=='references.qmd'):continue
 bad=[]
 for a,b in zip(r,r[1:]):
  if bibliography_sort_key(a[0])>bibliography_sort_key(b[0]):bad.append({'earlier':a[0],'earlier_line':a[1],'later':b[0],'later_line':b[1]})
 info={'file':p,'entries':len(r),'alphabetical':not bad,'inversions':bad}
 reference_lists.append(info)
 if bad:unsorted.append(info)
# Include Quarto brace IDs and literal HTML IDs, preserving file location semantics.
idpat=re.compile(r'\{[^}\n]*#([A-Za-z][\w:.-]*)[^}\n]*\}|\bid\s*=\s*["\x27]([^"\x27]+)["\x27]')
def ids(s):return [(m.group(1) or m.group(2),s[:m.start()].count('\n')+1) for m in idpat.finditer(s)]
allnewids=collections.defaultdict(list)
for p,s in current.items():
 for ident,line in ids(s):allnewids[ident].append({'file':p,'line':line})
lost=[];newids=[]
for p,s in old.items():
 curids={x for x,_ in ids(current.get(p,''))};oldids={x for x,_ in ids(s)}
 for ident,line in ids(s):
  if ident not in curids:lost.append({'file':p,'anchor':ident,'baseline_line':line,'current_other_locations':allnewids.get(ident,[])})
 for ident,line in ids(current.get(p,'')):
  if ident not in oldids:newids.append({'file':p,'anchor':ident,'current_line':line})
location_changes=[]
for key in oldworks.keys()&newworks.keys():
 before=sorted({x['file'] for x in oldworks[key]}-{'references.qmd'});after=sorted({x['file'] for x in newworks[key]}-{'references.qmd'})
 if before!=after:location_changes.append({'work_key':key,'reference':newworks[key][0]['reference'],'before_source_files':before,'after_source_files':after,'removed_locations':sorted(set(before)-set(after)),'added_locations':sorted(set(after)-set(before))})
variant_changes=[]
for key in oldworks.keys()&newworks.keys():
 before=sorted({normalize(x['reference']) for x in oldworks[key]});after=sorted({normalize(x['reference']) for x in newworks[key]})
 if before!=after:variant_changes.append({'work_key':key,'baseline_variants':list(dict.fromkeys(x['reference'] for x in oldworks[key])),'current_variants':list(dict.fromkeys(x['reference'] for x in newworks[key]))})
baseline=json.loads(Path('audits/developmental-revision-20260912/baseline.json').read_text());reviewfiles=[]
for p,h in baseline['preserved_review_files'].items():
 present=Path(p).exists();observed=hashlib.sha256(Path(p).read_bytes()).hexdigest() if present else None
 reviewfiles.append({'file':p,'expected_sha256':h,'observed_sha256':observed,'unchanged':observed==h})
# Read the configured files again at the end to detect a moving audit target.
hashes={p:hashlib.sha256(s.encode()).hexdigest() for p,s in current.items()}
changed_during=[p for p in paths if hashlib.sha256(Path(p).read_bytes()).hexdigest()!=hashes[p]]
result={'baseline_commit':BASELINE,'audited_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'configured_source_count':len(paths),'configured_paths_changed':{'removed':sorted(set(oldpaths)-set(paths)),'added':sorted(set(paths)-set(oldpaths))},'current_source_sha256':hashes,'changed_during_audit':changed_during,'reference_summary':{'baseline_occurrences':sum(len(refs(s)) for s in old.values()),'current_occurrences':sum(len(refs(s)) for s in current.values()),'baseline_unique_normalized_entries':len(oldentries),'current_unique_normalized_entries':len(newentries),'entries_added':len(newentries.keys()-oldentries.keys()),'entries_removed':len(oldentries.keys()-newentries.keys()),'baseline_work_keys':len(oldworks),'current_work_keys':len(newworks),'works_added':len(newworks.keys()-oldworks.keys()),'works_removed':len(oldworks.keys()-newworks.keys())},'added_entries':[{ 'key':k,'locations':newentries[k]} for k in sorted(newentries.keys()-oldentries.keys())],'removed_entries':[{'key':k,'locations':oldentries[k]} for k in sorted(oldentries.keys()-newentries.keys())],'added_works':[{'key':k,'locations':newworks[k]} for k in sorted(newworks.keys()-oldworks.keys())],'removed_works':[{'key':k,'locations':oldworks[k]} for k in sorted(oldworks.keys()-newworks.keys())],'variant_changes':variant_changes,'location_changes':location_changes,'reference_lists':reference_lists,'unsorted_lists':unsorted,'lost_explicit_anchors':lost,'added_explicit_anchors':newids,'preserved_review_files':reviewfiles,'method':{'scope':'All61sourcesin_quarto-html.yml atbaselineandcurrent; excludes generatedoutputs, unconfiguredsources and citationsoutside.referenceblocks.','entry_normalization':'Whitespace, case, final full stop, typographicquotes/dashes, italic/code markup and punctuation spacing normalized; author/date/title/content/URLs otherwise retained.','work_identity':'Author list + year + title prefix through first sentence break; Unicode accents/spacing/punctuation and URLs removed. Metadata variants withsamekeymanuallyreviewed; thisisnotDOIresolutionornewsourceverification.','order':'Independent regular-expression extraction of surname/initial pairs, or a corporate-name fallback, then year/suffix and title with initial A/An/The ignored. Names are compared letter-by-letter after accent/punctuation removal; author-list tuple prefixes put shorter lists first. This checks coauthor-aware alphabetization, not exhaustive APA style compliance.','anchors':'Explicit#identifiers insideQuartoattribute braces andliteralHTMLidattributes compared perfile; identifieslostlegacyURLs even ifanchor existselsewhere; auto-generatedheadinganchorsnotincluded.','snapshot':'CapturedsourceSHA256; rereadafterauditflagschangesduringexecution; laterrootmutationsrequiretargetedrecheck.'}}
Path('audits/developmental-revision-20260912/reference-preservation-check.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:result[k] for k in ('reference_summary','changed_during_audit','unsorted_lists','lost_explicit_anchors','removed_works','variant_changes')},ensure_ascii=False,indent=2))
